import assert from 'node:assert/strict';
import { writeFileSync, readFileSync } from 'node:fs';
import { lineFromRequest } from './src/api.js';
import { parseQuantity } from './src/quantity.js';
import { parseQuantity as parseCliQuantity } from './src/cli.js';

const zeroResult = lineFromRequest({ sku: ' A ', quantity: '0' });
assert.deepEqual(zeroResult, { sku: 'A', quantity: 0, active: false });
assert.deepEqual(lineFromRequest({ sku: ' A ', quantity: 0 }), zeroResult);
for (const [input, expected] of [[1, 1], [42, 42], ['1', 1], [' 2 ', 2], ['001', 1], ['1e2', 100]]) {
  assert.equal(parseQuantity(input), expected);
}
const invalid = [-1, -0.5, '-1', '-0.5', 0.5, 1.25, '0.5', NaN, Infinity, -Infinity, 'Infinity', '-Infinity', 'NaN', '', ' ', '\t\n', '\u00a0', true, false, null, undefined, 'abc', '0xG'];
for (const input of invalid) {
  assert.throws(() => parseQuantity(input), { name: 'Error', message: 'invalid quantity' });
}
assert.equal(parseCliQuantity(0), 1);
assert.equal(parseCliQuantity('0'), 1);
assert.equal(parseCliQuantity('-2'), -2);
let errorMessage;
try { parseQuantity('abc'); } catch (error) { errorMessage = error.message; }
const answer = { changed_file: 'src/quantity.js', zero_result: zeroResult, error_message: errorMessage };
writeFileSync('answer.json', `${JSON.stringify(answer, null, 2)}\n`);
assert.deepEqual(JSON.parse(readFileSync('answer.json', 'utf8')), answer);
console.log(JSON.stringify({ check: 'passed', invalid_cases: invalid.length, answer }));
